create table if not exists public.apps (id bigint generated by default as identity primary key,name text not null,version text,description text,download_url text not null,created_at timestamptz default now());
create table if not exists public.admins (user_id uuid primary key references auth.users(id) on delete cascade);
alter table public.apps enable row level security; alter table public.admins enable row level security;
create policy "Published apps visible to everyone" on public.apps for select using (true);
create policy "Admins insert apps" on public.apps for insert to authenticated with check (exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Admins update apps" on public.apps for update to authenticated using (exists(select 1 from public.admins where user_id=auth.uid())) with check (exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Admins delete apps" on public.apps for delete to authenticated using (exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Public downloads" on storage.objects for select using (bucket_id='apk-files');
create policy "Admins upload APK" on storage.objects for insert to authenticated with check (bucket_id='apk-files' and exists(select 1 from public.admins where user_id=auth.uid()));
create policy "Admins delete APK" on storage.objects for delete to authenticated using (bucket_id='apk-files' and exists(select 1 from public.admins where user_id=auth.uid()));
